def audit(job, label, pmid, status, reason, doi=None):
    m = META.get(str(pmid), {})
    AUDIT.append(dict(job=job, label=label, verified_pmid=str(pmid) if pmid else None, verified_doi=doi or m.get('doi'), title=m.get('title'), identity_status=status, decision_reason=reason))

